/** Mức XL IMP — filter + badge (GAP-IMP-VOUCHER-11). */
export const IMPORT_SAO_KE_PROCESSING_OPTIONS = [
  { value: '', label: 'Tất cả mức' },
  { value: '1', label: '1 — Draft' },
  { value: '3', label: '3 — Lập chứng từ' },
  { value: '5', label: '5 — Đã xác nhận' },
] as const;

export function formatImportSaoKeProcessingLevel(level: string | undefined): string {
  const lv = (level || '').trim();
  const hit = IMPORT_SAO_KE_PROCESSING_OPTIONS.find(o => o.value === lv);
  return hit?.label ?? (lv || '—');
}

/** Resume wizard step từ mức XL: 1→phân loại · 3/5→dry-run/confirm. */
export function resolveImportResumeStep(processingLevel: string | undefined): 3 | 4 {
  const lv = (processingLevel || '1').trim();
  if (lv === '3' || lv === '5') return 4;
  return 3;
}

