import { apiClient, unwrap, type BffResponse } from '../api';
import type {
  BankStatementImportRequest,
  BankStatementImportRow,
  BankStatementDryRunResult,
  BankStatementImportExecute,
  BankStatementImportResult,
  CustomerMatchResult,
  BatchDetailLine,
  CreateBankStatementImportVoucherRequest,
  BankStatementImportVoucher,
  UpdateBankStatementImportClassifyRequest,
  BankStatementImportDryRunPreview,
  BankStatementImportConfirmResult,
  BankStatementImportVoucherListItem,
  BankStatementImportVoucherListFilter,
  BankStatementExpenseImportFilter,
  ConfirmBankStatementImportDto,
  BankStatementCustomerBankMapPreview,
  ApplyBankStatementCustomerBankMapRequest,
  ApplyBankStatementCustomerBankMapResult,
  BankStatementImportPostingSummary,
} from './bankStatementImportModels';
import type { PagedResult } from './models';
import { parseBatchPaymentFilesToMap } from '../../utils/batchPaymentParse';

const BASE = '/accounting/bank-statements';
const IMP_BASE = '/accounting/bank-statement-imports';

function qs(params: Record<string, string | number | undefined>): string {
  const sp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === undefined || v === '') continue;
    sp.set(k, String(v));
  }
  return sp.toString();
}

export const bankStatementImportService = {
  matchCustomers: async (rows: BankStatementImportRow[], bankStatementFile?: string) => {
    const res = await apiClient.post<BffResponse<CustomerMatchResult>>(`${BASE}/match-customers`, {
      rows,
      bankStatementFile,
    });
    return unwrap(res);
  },

  dryRun: async (dto: BankStatementImportRequest) => {
    const res = await apiClient.post<BffResponse<BankStatementDryRunResult>>(`${BASE}/dry-run`, dto);
    return unwrap(res);
  },

  executeImport: async (dto: BankStatementImportExecute) => {
    const res = await apiClient.post<BffResponse<BankStatementImportResult>>(`${BASE}/import`, dto);
    return unwrap(res);
  },

  /** Danh sách chứng từ IMP (list page). */
  listImportVouchers: async (filter: BankStatementImportVoucherListFilter = {}) => {
    const q = qs({
      fromDate: filter.fromDate,
      toDate: filter.toDate,
      processingLevel: filter.processingLevel,
      search: filter.search,
      monthCode: filter.monthCode,
      page: filter.page ?? 1,
      pageSize: filter.pageSize ?? 20,
    });
    const res = await apiClient.get<BffResponse<PagedResult<BankStatementImportVoucherListItem>>>(
      `${IMP_BASE}?${q}`,
    );
    return unwrap(res);
  },

  /** Tạo chứng từ IMP (Step 2). */
  createImportVoucher: async (dto: CreateBankStatementImportVoucherRequest) => {
    const res = await apiClient.post<BffResponse<BankStatementImportVoucher>>(IMP_BASE, dto);
    return unwrap(res);
  },

  getImportVoucher: async (id: string) => {
    const res = await apiClient.get<BffResponse<BankStatementImportVoucher>>(`${IMP_BASE}/${id}`);
    return unwrap(res);
  },

  updateClassify: async (id: string, dto: UpdateBankStatementImportClassifyRequest) => {
    const res = await apiClient.put<BffResponse<BankStatementImportVoucher>>(`${IMP_BASE}/${id}`, dto);
    return unwrap(res);
  },

  /** Remap fill — 202 Accepted; FE GET lại CT. */
  remapClassify: async (id: string): Promise<{ id: string; code: string; scannedLineCount: number; updatedLineCount: number }> => {
    const res = await apiClient.post<BffResponse<{
      id?: string;
      code?: string;
      scannedLineCount?: number;
      updatedLineCount?: number;
      Id?: string;
      Code?: string;
      ScannedLineCount?: number;
      UpdatedLineCount?: number;
    }>>(`${IMP_BASE}/${id}/remap`);
    const data = unwrap(res);
    return {
      id: String(data.id ?? data.Id ?? id),
      code: String(data.code ?? data.Code ?? ''),
      scannedLineCount: Number(data.scannedLineCount ?? data.ScannedLineCount ?? 0),
      updatedLineCount: Number(data.updatedLineCount ?? data.UpdatedLineCount ?? 0),
    };
  },

  dryRunImportVoucher: async (id: string) => {
    const res = await apiClient.post<BffResponse<BankStatementImportDryRunPreview>>(`${IMP_BASE}/${id}/dry-run`);
    const data = unwrap(res) as BankStatementImportDryRunPreview & {
      ErrorLineCount?: number;
      ReadyLineCount?: number;
      ConfirmedLineCount?: number;
      ExpectedVouchers?: BankStatementImportDryRunPreview['expectedVouchers'];
    };
    return {
      importVoucherId: String((data as { importVoucherId?: string }).importVoucherId ?? id),
      importCode: String((data as { importCode?: string }).importCode ?? ''),
      errorLineCount: Number(data.errorLineCount ?? data.ErrorLineCount ?? 0),
      readyLineCount: Number(data.readyLineCount ?? data.ReadyLineCount ?? 0),
      confirmedLineCount: Number(data.confirmedLineCount ?? data.ConfirmedLineCount ?? 0),
      expectedVouchers: data.expectedVouchers ?? data.ExpectedVouchers ?? [],
    };
  },

  confirmImportVoucher: async (id: string, dto?: ConfirmBankStatementImportDto) => {
    const res = await apiClient.post<BffResponse<BankStatementImportConfirmResult>>(
      `${IMP_BASE}/${id}/confirm`,
      dto ?? {},
    );
    const data = unwrap(res) as BankStatementImportConfirmResult & {
      CreatedVoucherCount?: number;
      CreatedVoucherCodes?: string[];
      CreatedVouchers?: BankStatementImportConfirmResult['createdVouchers'];
      ErrorLineCount?: number;
      RemainingReadyLineCount?: number;
    };
    return {
      importVoucherId: String(data.importVoucherId ?? id),
      importCode: String(data.importCode ?? ''),
      processingLevel: String(data.processingLevel ?? ''),
      createdVoucherCount: Number(data.createdVoucherCount ?? data.CreatedVoucherCount ?? 0),
      createdVoucherCodes: data.createdVoucherCodes ?? data.CreatedVoucherCodes ?? [],
      errorLineCount: Number(data.errorLineCount ?? data.ErrorLineCount ?? 0),
      remainingReadyLineCount: Number(data.remainingReadyLineCount ?? data.RemainingReadyLineCount ?? 0),
      createdVouchers: data.createdVouchers ?? data.CreatedVouchers ?? [],
    };
  },

  /** Xóa IMP — cấm mức 5 / đã có CT con (BE). */
  deleteImportVoucher: async (id: string) => {
    const res = await apiClient.delete<BffResponse<boolean>>(`${IMP_BASE}/${id}`);
    return unwrap(res);
  },

  /** Chip filter mặc định — CP không cần gán lô (ShowOnImportFilter). */
  getExpenseImportFilters: async (): Promise<BankStatementExpenseImportFilter[]> => {
    const res = await apiClient.get<BffResponse<BankStatementExpenseImportFilter[]>>(
      `${IMP_BASE}/expense-filters`,
    );
    return unwrap(res) ?? [];
  },

  getCustomerBankMapPreview: async (
    importId: string,
    params: { customerCode: string; bankAccountNumber?: string },
  ) => {
    const q = qs({
      customerCode: params.customerCode,
      bankAccountNumber: params.bankAccountNumber,
    });
    const res = await apiClient.get<BffResponse<BankStatementCustomerBankMapPreview>>(
      `${IMP_BASE}/${importId}/customer-bank-map-preview?${q}`,
    );
    return unwrap(res);
  },

  applyCustomerBankMap: async (
    importId: string,
    dto: ApplyBankStatementCustomerBankMapRequest,
  ) => {
    const res = await apiClient.post<BffResponse<ApplyBankStatementCustomerBankMapResult>>(
      `${IMP_BASE}/${importId}/apply-customer-bank-map`,
      dto,
    );
    return unwrap(res);
  },

  /** Tab Định khoản — group Đơn vị cơ sở → ĐK + tiền. */
  getPostingSummary: async (importId: string): Promise<BankStatementImportPostingSummary> => {
    const res = await apiClient.get<BffResponse<BankStatementImportPostingSummary>>(
      `${IMP_BASE}/${importId}/posting-summary`,
    );
    return unwrap(res);
  },
};

/** Parse batch payment files → map theo batchRef (MB bulk + TCB Payroll · xlsx/csv). */
export function parseBatchPaymentFiles(
  files: File[],
): Promise<Map<string, BatchDetailLine[]>> {
  return parseBatchPaymentFilesToMap(files);
}

